func TestCustomCategoryAndFailures(t *testing.T) {
	RegisterOps("unit", map[string]OpHandler{
		"echo": func(_ context.Context, _ *Env, args map[string]any) (any, error) { return args["value"], nil },
		"fail": func(context.Context, *Env, map[string]any) (any, error) {
			return nil, zipkin.NewError(zipkin.ErrorCodeNotFound, "nope", nil)
		},
		"plainfail": func(context.Context, *Env, map[string]any) (any, error) { return nil, errors.New("plain") },
		"panic":     func(context.Context, *Env, map[string]any) (any, error) { panic("boom") },
		"counted":   func(context.Context, *Env, map[string]any) (any, error) { return counted(5), nil },
	})
	RegisterExpectation("isFive", func(_ *Env, result, _ any) error {
		if result != counted(5) {
			return errors.New("not five")
		}
		return nil
	})
	RegisterExpectation("keyed", func(env *Env, _, want any) error {
		if _, ok := want.(map[string]any)["root-"+env.Run]; !ok {
			return errors.New("expectation keys were not expanded")
		}
		return nil
	})
	dir := t.TempDir()
	writeScenario(t, dir, "ok.json", `{"id":"unit.ok","category":"unit","steps":[
		{"op":"echo","expect":{"keyed":{"root-${run}":["child"]}}},
		{"op":"echo","args":{"value":"hello ${run} ${prefix} ${serviceName} ${unknown"},"save":"greeting"},
		{"op":"echo","args":{"value":"${greeting}!"},"expect":{"contains":"hello","notContains":"bye","type":"string"}},
		{"op":"echo","args":{"value":{"n":[1,"${run}"]}},"save":"obj","expect":{"equals":{"n":[1,"${run}"]},"count":1}},
		{"op":"echo","args":{"value":"${obj}"},"expect":{"contains":"\"n\""}},
		{"op":"echo","args":{"value":[{"name":"a"},{"name":"b"}]},"expect":{"sorted":true,"minCount":2,"contains":{"name":"b"}}},
		{"op":"echo","args":{"value":true},"expect":{"true":true,"notNull":true,"type":"boolean"}},
		{"op":"echo","args":{"value":null},"expect":{"null":true,"type":"null","count":0}},
		{"op":"fail","expect":{"error":"NOT_FOUND"}},
		{"op":"counted","expect":{"count":5,"isFive":true}},
		{"op":"echo","args":{"value":"secret-${run}"},"expect":{"stringForm":{"contains":"secret-","notContains":"other"}}},
		{"op":"echo","requires":["missing-cap"]}
	]}`)
	rep, err := RunScenarios(t.Context(), dir, Options{Categories: []string{"unit"}, Factories: Factories{"unit": func(context.Context, *Env) (any, error) { return nil, nil }}, ServiceName: "svc"})
	if err != nil || !rep.OK() || rep.Passed != 1 {
		t.Fatalf("report %+v err %v", rep, err)
	}

	failures := map[string]string{
		`{"op":"nosuch"}`: "unsupported op",
		`{"op":"panic"}`:  "panicked",
		`{"op":"fail"}`:   "unexpected error",
		`{"op":"echo","args":{"value":1},"expect":{"error":"NOT_FOUND"}}`:                 "got success",
		`{"op":"plainfail","expect":{"error":"NOT_FOUND"}}`:                               "non-SDK error",
		`{"op":"fail","expect":{"error":"CONFLICT"}}`:                                     "got NOT_FOUND",
		`{"op":"echo","args":{"value":"x"},"expect":{"reveal":"x"}}`:                      "no Reveal",
		`{"op":"echo","args":{"value":"x"},"expect":{"null":true}}`:                       "null=true",
		`{"op":"echo","expect":{"notNull":true}}`:                                         "notNull=true",
		`{"op":"echo","args":{"value":"x"},"expect":{"true":true}}`:                       "not a boolean",
		`{"op":"echo","args":{"value":false},"expect":{"true":true}}`:                     "got false",
		`{"op":"echo","args":{"value":{"a":1}},"expect":{"equals":{"a":2}}}`:              "want",
		`{"op":"echo","args":{"value":"abc"},"expect":{"contains":"z"}}`:                  "contains",
		`{"op":"echo","args":{"value":"abc"},"expect":{"notContains":"a"}}`:               "notContains",
		`{"op":"echo","args":{"value":1},"expect":{"count":1}}`:                           "no size",
		`{"op":"echo","args":{"value":[1]},"expect":{"count":2}}`:                         "want count 2",
		`{"op":"echo","args":{"value":[1]},"expect":{"minCount":2}}`:                      "want minCount 2",
		`{"op":"echo","args":{"value":["b","a"]},"expect":{"sorted":true}}`:               "not sorted",
		`{"op":"echo","args":{"value":"x"},"expect":{"sorted":true}}`:                     "not sorted",
		`{"op":"echo","args":{"value":1},"expect":{"type":"string"}}`:                     "got type number",
		`{"op":"echo","args":{"value":"x"},"expect":{"stringForm":"bad"}}`:                "needs an object",
		`{"op":"echo","args":{"value":"xy"},"expect":{"stringForm":{"notContains":"x"}}}`: "forbidden",
		`{"op":"echo","args":{"value":"xy"},"expect":{"stringForm":{"contains":"z"}}}`:    "does not contain",
		`{"op":"echo","expect":{"whatever":1}}`:                                           "unsupported expectation",
		`{"op":"counted","expect":{"isFive":true}}`:                                       "",
		`{"op":"echo","args":{"value":1},"expect":{"isFive":true}}`:                       "not five",
	}
	for step, want := range failures {
		dir := t.TempDir()
		writeScenario(t, dir, "f.json", `{"id":"unit.fail","category":"unit","steps":[`+step+`]}`)
		rep, _ := RunScenarios(t.Context(), dir, Options{Factories: Factories{"unit": func(context.Context, *Env) (any, error) { return nil, nil }}, ScenarioTimeout: time.Minute})
		res := rep.Results[0]
		if want == "" {
			if res.Status != StatusPassed {
				t.Errorf("%s: %s", step, res.Reason)
			}
			continue
		}
		if res.Status != StatusFailed || !strings.Contains(res.Reason, want) {
			t.Errorf("%s: status %s reason %q, want %q", step, res.Status, res.Reason, want)
		}
	}
}

func TestPollingOps(t *testing.T) {
	var calls atomic.Int32
	RegisterOps("pollunit", map[string]OpHandler{
		"eventually": func(_ context.Context, _ *Env, args map[string]any) (any, error) {
			n := int(calls.Add(1))
			if n < ArgInt(args, "after", 3) {
				if n == 1 {
					return nil, zipkin.NewError(zipkin.ErrorCodeUnavailable, "warming up", nil)
				}
				return []any{"other"}, nil
			}
			return []any{"other", "svc"}, nil
		},
		"unsupported": func(context.Context, *Env, map[string]any) (any, error) {
			calls.Add(1)
			return nil, zipkin.UnsupportedError("op", "no")
		},
		"panics": func(context.Context, *Env, map[string]any) (any, error) { calls.Add(1); panic("boom") },
	})
	for _, op := range []string{"eventually", "unsupported", "panics"} {
		RegisterPollingOp("pollunit", op)
	}
	factories := Factories{"pollunit": func(context.Context, *Env) (any, error) { return nil, nil }}
	run := func(step string, timeout time.Duration) ScenarioResult {
		t.Helper()
		calls.Store(0)
		dir := t.TempDir()
		writeScenario(t, dir, "p.json", `{"id":"pollunit.p","category":"pollunit","steps":[`+step+`]}`)
		rep, err := RunScenarios(t.Context(), dir, Options{Factories: factories, ScenarioTimeout: timeout})
		if err != nil {
			t.Fatal(err)
		}
		return rep.Results[0]
	}
	if res := run(`{"op":"eventually","args":{"intervalMs":1},"expect":{"contains":"svc"},"save":"list"}`, time.Minute); res.Status != StatusPassed || calls.Load() != 3 {
		t.Fatalf("polling until the expectation passes: %+v (calls %d)", res, calls.Load())
	}
	res := run(`{"op":"eventually","args":{"after":1000,"intervalMs":5,"timeoutMs":30},"expect":{"contains":"svc"}}`, time.Minute)
	if res.Status != StatusFailed || !strings.Contains(res.Reason, "contains") || calls.Load() < 2 {
		t.Fatalf("timeout reports the last failure: %+v (calls %d)", res, calls.Load())
	}
	if res := run(`{"op":"unsupported","args":{"intervalMs":1},"expect":{"contains":"svc"}}`, time.Minute); res.Status != StatusFailed || calls.Load() != 1 {
		t.Fatalf("non-retryable errors stop polling: %+v (calls %d)", res, calls.Load())
	}
	if res := run(`{"op":"panics","args":{"intervalMs":1}}`, time.Minute); res.Status != StatusFailed || calls.Load() != 1 {
		t.Fatalf("panics stop polling: %+v (calls %d)", res, calls.Load())
	}
	res = run(`{"op":"eventually","args":{"after":1000,"intervalMs":20,"timeoutMs":60000},"expect":{"contains":"svc"}}`, 50*time.Millisecond)
	if res.Status != StatusFailed || !strings.Contains(res.Reason, "scenario ended while polling") {
		t.Fatalf("scenario timeout ends polling: %+v", res)
	}
}

