type revealer struct {
	value string
	err   error
}

func (r *revealer) Reveal() (string, error) { return r.value, r.err }

func TestRevealExpectation(t *testing.T) {
	env := newEnv(&Scenario{}, Options{})
	if err := checkOne(env, "reveal", "abc", &revealer{value: "abc"}); err != nil {
		t.Fatal(err)
	}
	if err := checkOne(env, "reveal", "zzz", &revealer{value: "abc"}); err == nil {
		t.Fatal("different value")
	}
	if err := checkOne(env, "reveal", "x", &revealer{err: errors.New("binary")}); err == nil {
		t.Fatal("reveal error")
	}
	var nilValue *revealer
	if err := checkOne(env, "reveal", "x", nilValue); err == nil {
		t.Fatal("nil value")
	}
	if !isNil(nilValue) || isNil(3) || !isNil(nil) {
		t.Fatal("isNil")
	}
}

func TestHelpers(t *testing.T) {
	args := map[string]any{"s": "x", "n": 2.0, "b": true, "m": map[string]any{"k": 1}, "l": []any{"a", 1.0}, "ms": 1500.0, "nil": nil}
	if ArgString(args, "s") != "x" || ArgString(args, "n") != "2" || ArgString(args, "none") != "" || ArgString(args, "nil") != "" {
		t.Fatal("ArgString")
	}
	if ArgInt(args, "n", 0) != 2 || ArgInt(args, "s", 7) != 7 {
		t.Fatal("ArgInt")
	}
	if !ArgBool(args, "b") || ArgBool(args, "s") {
		t.Fatal("ArgBool")
	}
	if ArgMap(args, "m")["k"] != 1 || ArgMap(args, "s") != nil {
		t.Fatal("ArgMap")
	}
	if l := ArgStrings(args, "l"); len(l) != 2 || l[1] != "1" || ArgStrings(args, "s") != nil {
		t.Fatal("ArgStrings")
	}
	if ArgDuration(args, "ms", 0) != 1500*time.Millisecond || ArgDuration(args, "s", time.Second) != time.Second {
		t.Fatal("ArgDuration")
	}
	if stringify(nil) != "" || stringify(map[string]int{"a": 1}) != `{"a":1}` || stringify(make(chan int)) == "" {
		t.Fatal("stringify")
	}
	if Normalize(make(chan int)) == nil || toInt("x") != -1 || toInt(3) != 3 {
		t.Fatal("normalize/toInt")
	}
	if containsValue(map[string]any{"k": 1}, "k") != true || containsValue(3.0, 3.0) {
		t.Fatal("containsValue")
	}
	if subsetEqual(map[string]any{"a": 1.0}, "x") || subsetEqual([]any{1.0}, []any{}) || subsetEqual([]any{1.0}, []any{2.0}) {
		t.Fatal("subsetEqual")
	}
	if describe(3) != "int" || jsonString(map[string]int{}) != "{}" {
		t.Fatal("describe")
	}
	env := newEnv(&Scenario{}, Options{Prefix: "p-${run}"})
	env.Vars["x"] = "1"
	if env.Prefix != "p-"+env.Run || env.Expand("a${x}b${x}") != "a1b1" || env.Expand("plain") != "plain" {
		t.Fatal("expand")
	}
	if v := env.ExpandValue([]any{"${x}", 2.0}).([]any); v[0] != "1" {
		t.Fatal("expand slice")
	}
	keys := env.ExpandValue(map[string]any{"root-${run}": []any{"child-${x}"}, "plain": map[string]any{"${x}": "${x}"}}).(map[string]any)
	if kids, ok := keys["root-"+env.Run].([]any); !ok || kids[0] != "child-1" || keys["plain"].(map[string]any)["1"] != "1" {
		t.Fatalf("object keys must be expanded: %v", keys)
	}
	if len(randomRunID()) != 8 {
		t.Fatal("run id")
	}
	if _, err := coreTarget(&Env{Target: 3}); err == nil {
		t.Fatal("core target type")
	}
}
